<?php
$backend=getenv('ELVARQO_BACKEND')?:dirname(__DIR__,2).'/backend';require $backend.'/vendor/autoload.php';$app=require $backend.'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Crypt;use Illuminate\Support\Facades\Storage;use App\Fulfilment\Shipments;use App\Fulfilment\Tracking;use App\AfterSales\Returns;use App\AfterSales\Refunds;
$root=realpath(getenv('QA_PRIVATE_ROOT')?:'');if(getenv('ELVARQO_QA_ENABLED')!=='1'||!app()->environment('local')||!$root||realpath(dirname(config('database.connections.sqlite.database')))!==$root){fwrite(STDERR,'Isolated QA database required.');exit(2);}
$d=json_decode(file_get_contents($root.'/fulfilment-private.json'),true);$action=$argv[1]??'';
if($action==='delivered'){$v=$d['parcel'];$v['items'][0]['quantity']=2;$q=app(Shipments::class)->quote($d['order_id'],$v,$d['actor']);$f=app(Shipments::class)->prepare($d['order_id'],$q['id'],$d['actor']);app(Shipments::class)->book($f->id,$d['actor']);app(Shipments::class)->dispatch($f->id,$d['actor']);$f=DB::table('order_fulfilments')->find($f->id);$body=json_encode(['id'=>'qa_delivery','provider_reference'=>$f->provider_reference,'tracking_number'=>$f->tracking_number,'state'=>'delivered','occurred_at'=>now()->toISOString()]);$t=time();app(Tracking::class)->event($body,'t='.$t.',v1='.hash_hmac('sha256',$t.'.'.$body,config('fulfilment.webhook_secret')));echo 'delivered';}
elseif($action==='latest-link'){$purpose=$argv[2];$email=$argv[3]??'';$n=DB::table('customer_notifications')->orderByDesc('created_at')->get()->filter(function($n)use($purpose,$email){$p=json_decode(Crypt::decryptString($n->encrypted_payload),true);return $p['purpose']===$purpose && (!$email||$p['email']===$email);})->last();if(!$n)throw new RuntimeException('No matching private email');$text=Storage::disk('local')->get('customer-notifications/'.$n->id.'.eml');preg_match('~https?://[^\s]+#purpose=[a-z]+&token=[a-f0-9]{64}~',$text,$m);echo $m[0];}
elseif($action==='wishlist-full'){ $c=DB::table('customers')->where('email','alpha@example.test')->first();$count=DB::table('customer_saved_items')->where('customer_id',$c->id)->count();for($i=20001;$count<500;$i++,$count++)DB::table('customer_saved_items')->insert(['customer_id'=>$c->id,'product_id'=>$i,'variant_id'=>null,'created_at'=>now()]);echo 'full';}
elseif($action==='wishlist-large'){ $c=DB::table('customers')->where('email','alpha@example.test')->first();for($i=10001;$i<=10055;$i++)DB::table('customer_saved_items')->insertOrIgnore(['customer_id'=>$c->id,'product_id'=>$i,'variant_id'=>null,'created_at'=>now()]);echo 'seeded';}
elseif($action==='stockrestore'){DB::table('stock_balances')->where('variant_id',$d['variant'])->update(['on_hand'=>1]);DB::table('catalogue_variants')->where('id',$d['variant'])->update(['price_minor'=>5000]);echo 'restored';}
elseif($action==='replacement'){echo json_encode(DB::table('exchange_links as e')->join('commerce_orders as o','o.id','=','e.replacement_order_id')->first(['o.id','o.reference','o.payment_state','e.difference_minor']));}
elseif($action==='stockout'){DB::table('stock_balances')->where('variant_id',$d['variant'])->update(['on_hand'=>0]);echo 'out';}
elseif($action==='summary'){echo json_encode(['returns'=>DB::table('after_sales_returns')->count(),'claims'=>DB::table('return_unit_claims')->count(),'inspections'=>DB::table('return_inspections')->count(),'restocks'=>DB::table('after_sales_stock_events')->count(),'refunds'=>DB::table('refund_attempts')->count(),'receipts'=>DB::table('sandbox_refund_receipts')->count(),'exchanges'=>DB::table('exchange_links')->count(),'states'=>DB::table('refund_attempts')->pluck('state')->all(),'on_hand'=>(int)DB::table('stock_balances')->sum('on_hand'),'reserved'=>(int)DB::table('stock_balances')->sum('reserved'),'product_id'=>DB::table('catalogue_variants')->where('id',$d['variant'])->value('product_id'),'variant_id'=>$d['variant']]);}

elseif($action==='accept-return'){$r=DB::table('after_sales_returns')->first();$v=['received_quantity'=>$r->quantity,'location_id'=>$d['parcel']['location_id'],'outcome'=>'accepted_resellable','reason'=>'Concurrency inspection','confirmed'=>true];app(Returns::class)->inspect($r->id,$v,$d['actor']);echo 'accepted';}
elseif($action==='seed-exchanges'){foreach([0,1]as $n){$v=['operation_id'=>(string)\Illuminate\Support\Str::uuid(),'order_item_id'=>$d['parcel']['items'][0]['order_item_id'],'quantity'=>1,'reason'=>'size','resolution'=>'exchange','exchange_variant_id'=>$d['variant'],'comments'=>'','confirmed'=>true];$r=app(Returns::class)->request(DB::table('commerce_orders')->find($d['order_id']),\Illuminate\Http\Request::create('/','POST',$v));app(Returns::class)->inspect($r['id'],['received_quantity'=>1,'location_id'=>$d['parcel']['location_id'],'outcome'=>'accepted_damaged','reason'=>'Concurrency inspection','confirmed'=>true],$d['actor']);}DB::table('catalogue_variants')->where('id',$d['variant'])->update(['price_minor'=>5000]);DB::table('stock_balances')->where('variant_id',$d['variant'])->update(['on_hand'=>1]);echo 'seeded';}
elseif(str_starts_with($action,'race-')){$n=(int)$argv[2];touch($root.'/ready-'.$n);$end=microtime(true)+20;while(!file_exists($root.'/go')){if(microtime(true)>$end)exit(3);usleep(10000);}try{
 if($action==='race-claim'){$v=['operation_id'=>$n?'d2f53bf2-a105-42a6-87b2-60a40ef0fa22':'d2f53bf2-a105-42a6-87b2-60a40ef0fa11','order_item_id'=>$d['parcel']['items'][0]['order_item_id'],'quantity'=>2,'reason'=>'size','resolution'=>'refund','comments'=>'','confirmed'=>true];$r=app(Returns::class)->request(DB::table('commerce_orders')->find($d['order_id']),\Illuminate\Http\Request::create('/','POST',$v));echo json_encode(['result'=>'claimed']);}
 elseif($action==='race-refund'||$action==='race-replay'){$r=DB::table('after_sales_returns')->first();$v=['operation_id'=>$action==='race-replay'?DB::table('refund_attempts')->value('id'):($n?'d2f53bf2-a105-42a6-87b2-60a40ef0fb22':'d2f53bf2-a105-42a6-87b2-60a40ef0fb11'),'amount_minor'=>$r->credit_minor,'reason'=>'Concurrency full credit','scenario'=>'succeed','confirmed'=>true];$a=app(Refunds::class)->start($r->id,$v,$d['actor']);echo json_encode(['result'=>$a['state']]);}
 elseif($action==='race-exchange'){$r=DB::table('after_sales_returns')->orderBy('id')->offset($n)->first();$v=['operation_id'=>$n?'d2f53bf2-a105-42a6-87b2-60a40ef0fc22':'d2f53bf2-a105-42a6-87b2-60a40ef0fc11','variant_id'=>$d['variant'],'expected_difference_minor'=>5000-$r->credit_minor,'confirmed'=>true];$e=app(\App\AfterSales\Exchanges::class)->issue($r->id,$v,$d['actor']);echo json_encode(['result'=>$e['state']]);}
 }catch(\Illuminate\Validation\ValidationException $e){echo json_encode(['result'=>'unavailable','errors'=>$e->errors()]);}}
else{fwrite(STDERR,'Unknown private Phase 8 action');exit(2);}
